72			entries := passOrder[r.ID]
73			sort.SliceStable(entries, func(i, j int) bool { return entries[i].seq < entries[j].seq })
74			for _, en := range entries {
75				st.PassedEnrollmentIDs = append(st.PassedEnrollmentIDs, en.id)
76			}
77	
78			if w := s.validWaiver(studentID, r.ID); w != nil {
