90			if st.Satisfied && st.Course != nil {
91				rep.TotalCredits += st.Course.Credit
92			} else {
93				rep.Unmet = append(rep.Unmet, r.ID)
94			}
95			rep.Requirements = append(rep.Requirements, st)
96		}
97	
98		for _, w := range s.waivers {
99			if w.StudentID != studentID {
100				continue
101			}
102			switch w.Status {
